/**
 *
 * 그리드 최저매각가격 메서드
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.07.03.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.lwsPrcFormat = function (data, formattedData, rowIndex, colIndex) {
    let result = '<div style="white-space:nowrap;">';
    if (dlt_srchResult.getCellData(rowIndex, "notifyMinmaePrice2") != 0) {
        result += `${_IMG1} ${scutilo.getCommaFmt(data)} <br>${_IMG2} ${scutilo.getCommaFmt(dlt_srchResult.getCellData(rowIndex, "notifyMinmaePrice2"))}`
        if (dlt_srchResult.getCellData(rowIndex, "notifyMinmaePrice3") != 0) {
            result += `<br>${_IMG3} ${scutilo.getCommaFmt(dlt_srchResult.getCellData(rowIndex, "notifyMinmaePrice3"))}`
            if (dlt_srchResult.getCellData(rowIndex, "notifyMinmaePrice4") != 0) {
                result += `<br>${_IMG4} ${scutilo.getCommaFmt(dlt_srchResult.getCellData(rowIndex, "notifyMinmaePrice4"))}`
            }
        }
    } else {
        result += scutilo.getCommaFmt(data);
    }
    result += `<br>(${Math.floor((Number(data) / Number(dlt_srchResult.getCellData(rowIndex, "gamevalAmt"))) * 100)}%)`;
    result += '</div>';
    return result;
}

