 * ============= ============ ==========================
 *  2024.09.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 *
 */
scwin.tooltipFormatter = function (rowIndex, colIndex, label, isOverflow) {
    var txt = "";
    var _colId = dlt_srchResult.getColumnID(colIndex);
    if (_colId == "jpDeptNm") {
        let time = "";
        if (!scutilo.isEmpty(dlt_srchResult.getCellData(rowIndex, "maeHh2"))) time += `,${scwin.timeFormat(dlt_srchResult.getCellData(rowIndex, "maeHh2"))}`;
        if (!scutilo.isEmpty(dlt_srchResult.getCellData(rowIndex, "maeHh3"))) time += `,${scwin.timeFormat(dlt_srchResult.getCellData(rowIndex, "maeHh3"))}`;
        if (!scutilo.isEmpty(dlt_srchResult.getCellData(rowIndex, "maeHh4"))) time += `,${scwin.timeFormat(dlt_srchResult.getCellData(rowIndex, "maeHh4"))}`;
        const dxdyYmd = `${scdateo.getFmtDate(dlt_srchResult.getCellData(rowIndex, "maeGiil"), ".")} ${scwin.timeFormat(dlt_srchResult.getCellData(rowIndex, "maeHh1"))} ${time}`;
        const maePlace = dlt_srchResult.getCellData(rowIndex, "maePlace");
        txt = `<div class="toolTipText">
        <span><text class="mr5" style="color:#6798FD; width:16px;">매각기일</text>${dxdyYmd}</span><br/>
        <span><text class="mr5" style="color:#6798FD; width:16px;">매각장소</text>${maePlace}</span></div>`;
    }

    return txt;
}


/**
 *
 * 주소 상세 페이지 이동
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.07.03.   나해준       [NELS]최초 생성
 *  2025.12.26.   공태은       [25A-PGJ-0052] 기일별 검색 목록 화면에서 상세 화면에서 목록화면으로 이동시 스크롤바 유지되도록 개선
 *  2025.12.26.   공태은       [25A-PGJ-0053] 나의경매 자주쓰는검색 화면에서 페이지 이동시 검색조건이 초기화되는 현상 수정
 * ============= ============ ==========================
 */
function moveDtlPage(index) {
    const csNo = dlt_srchResult.getCellData(index, 'srnSaNo');
    const cortOfcCd = dlt_srchResult.getCellData(index, 'boCd');
    const dspslGdsSeq = dlt_srchResult.getCellData(index, 'maemulSer');
    const lclsUtilCd = dlt_srchResult.getCellData(index, 'lclsUtilCd');
    const mclsUtilCd = dlt_srchResult.getCellData(index, 'mclsUtilCd');
    const srchInfo = dma_srchGdsDtlSrchInfo.getJSON();

    //상세 화면으로 이동시 목록화면의 스크롤 위치 정보를 저장
    const scrollTop = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop;
    srchInfo.srchRowIndex = scrollTop;

    if(scutilo.isEmpty(srchInfo.sideDvsCd)){
        srchInfo.sideDvsCd = '2';
    }

    srchInfo.menuNm = scwin.menuNm;
    const pgmId = scwin.pgmId;

    let obj = {
        "dataObject": {
            "type": "json",
            "name": "param",
            "data": {
                csNo, cortOfcCd, dspslGdsSeq, pgmId, srchInfo
                , prevInfo: { prevPgmId: 'PGJ151M01', pageNum: dma_pageInfo.get('pageNo') }
            }
        }
    };

    if (lclsUtilCd == "30000" && (mclsUtilCd == "30100" || mclsUtilCd == "31100")) {
        $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ154M03.xml', obj);
    } else {
        $p.main().wfm_mainFrame.setSrc('/pgj/ui/pgj100/PGJ15BM01.xml', obj);
    }

}

