/**
 * 물건 비교 팝업창을 오픈하는 이벤트
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.06.27.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.gdsCmprsPopUpOpenEvent = function () {

    let checkedData = grd_gdsDtlSrchResult.getCheckedJSON("checkBox");
    var uniqueChkData = [];
    var setVal = new Set();
    checkedData.forEach(function(i){
        if(!setVal.has(i.colMerge)){ //merging시 중복 제거
            uniqueChkData.push(i);
            setVal.add(i.colMerge);
        }
    });
    checkedData = uniqueChkData;

    if (checkedData.length === 0 || checkedData.length === 1) {
        scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pgjmsg.PGJ.W_0054))
        return
    } else if (checkedData.length > 3) {
        scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pgjmsg.PGJ.W_0054))
        return;
    } else {
        const param = JSON.stringify(checkedData.map((data) => {
            return {
                cortOfcCd: data.boCd,
                csNo: data.saNo,
                dspslGdsSeq: data.maemulSer,
                pgmId: scwin.pgmId,
                prevPgmId : scwin.prevPgmId
            }
        }))
        const popId = 'gdsCmprs'
        if (pgjUtil.popupDpcnChk(popId)) {
            scwin.gdsCmprsPopUp(param)
        } else {
            return;
        }
    }
}



/**
 * 관심물건등록 팝업
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.itrtGdsRegPopUp = function (checkLst) {

    /********* Popup Settings *********/
    const winW = window.innerWidth;
    const winH = window.innerHeight;

    /* small popup size */
    const popupW = 700;
    const popupH = 400;

    const popupX = (winW / 2) - (popupW / 2);
    const popupY = (winH / 2) - (popupH / 2);

    /**
     * openPopUp option설정
     */
    var options = {
        id: "itrtGdsRegPopUp",
        type: "wframePopup",
        popupName: "관심물건등록",
        top: popupY,
        left: popupX,
        width: popupW,
        height: popupH,
        modal: false
    };
    obj = {};
    let baseInfo = {
        cortDvsCd: "B",//동산,부동산 구분코드
        cortAuctnMbrsId: scwin.lgnMbr || ''
    }
    paramObj = {};
    paramObj.checkLst = checkLst;
    paramObj.baseInfo = baseInfo;
    obj.paramObj = paramObj;
    /* 관심물건등록 팝업창 open  */
    com.win.openPopup("/pgj/ui/pgj100/PGJ15BP07.xml", options, obj);
};

