/**
 * 페이지당 변경시 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.11.13.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_pageSize_onviewchange = function(info) {

    var cookieFlag = info.newValue;
    if (cookieFlag == 10) {
        pgjUtil.setCookie('pageCnt','10')
    } else if (cookieFlag == 20) {
        pgjUtil.setCookie('pageCnt','20')
    } else if (cookieFlag == 30) {
        pgjUtil.setCookie('pageCnt','30');
    } else if (cookieFlag == 40) {
        pgjUtil.setCookie('pageCnt','40');
    }
    scwin.pageNum = 1;
    scwin.pageSize = info.newValue;
    scwin.gdsDtlSrchMain(true, info.newValue);//조회처리
};

/**
 * 프린트 이벤트
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.06.27.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.printBtnOnclick = function(e) {
    let paramJSON = {};
    paramJSON.html = document.getElementById($p.getComponentById('grp_contests').id).innerHTML;

    var dataObject = {
            type : "json",
            data : paramJSON,
            name : "paramObj"
    };

    /* default popup size */
    const winW = window.innerWidth;
    const winH = window.innerHeight;
    const popupW = 1200;
    const popupH = 700;

    const popupX = (winW / 2) - (popupW / 2);
    const popupY = (winH / 2) - (popupH / 2);

    // 팝업의 옵션
    var options = {
            id: 'print',					// 팝업ID
            type: "browserPopup",			// 팝업 타입(wframePopup,browserPopup)
            width: popupW,				// 팝업 가로사이즈
            height: popupH,			// 팝업 세로사이즈
            top: popupY,					// 팝업 top위치
            left: popupX,				// 팝업 left위치
            popupName: "프린트",				// 팝업 Name
            modal: false,					// 부모창이 안움직임(true)/부모창이 움직임(false)
            useIFrame: true,
            dataObject : dataObject
    };

    $p.openPopup("/pgj/ui/pgj100/PGJPrintContainer.xml", options);
};
